Definition hblk8 (LB : list ablock) (X n : Z) : Prop :=
  exists p A N, In (mkABlock (ABHeap p) A N) LB /\ N mod 8 = 0 /\ A <= X /\ X + n <= A + N.

(* [comment removed for export] *)
Definition zshadow (m : amem) (A n : Z) : Prop := forall a, A <= a < A + n -> m (wa (shad a)) = Some (Z_to_bv 8 0).

