(* [comment removed for export] *)
(* [comment removed for export] *)
Definition fse_build_postA (L : alayout) (RNG : footprint)
    (ra gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (FR : bvmap 5 word) (fc : bv 32)
    (st : astate) (LB : list ablock) (SPV DT WK msv tl : Z) (d : dtable) (lo : Z) (m : amem)
    : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra (Z_to_bv 64 SPV) gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 0) a1 a2 a3 a4 a5 a6 a7
                 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             FR (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ mem_inv bsegs m' /\ stk bsegs m' lo SPV
    /\ magree bsegs (fun a => aclient_addr CI LB SPV a /\ ~ (DT <= a < DT + FSE_DTABLE_SIZE tl)
                              /\ ~ (WK <= a < WK + FSE_BUILD_DTABLE_WKSP_SIZE tl msv)) m m'
    /\ AHEAP AI L RNG st LB m'
    /\ u8arr bsegs m' DT (fse_dt_bytes d).

Definition fse_build_stmtA : Prop :=
  forall (L : alayout) (RNG : footprint)
         (ra gp tp t0 t1 t2 s0 s1 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
         (FR : bvmap 5 word) (fc : bv 32) (m : amem) (st : astate) (LB : list ablock)
         (SPV DT NC WK wks msv tl : Z) (nc : list Z) (jdt jw : list byte) (d : dtable) (lo : Z),
  (* [comment removed for export] *)
  build_dtable nc msv tl wks = Ok d -> 0 <= msv -> 0 <= wks < 2^64 ->
  AHEAP AI L RNG st LB m ->
  (forall b, In b LB -> ablk (ab_addr b) (ab_addr b + ab_size b)) ->
  (* [comment removed for export] *)
  u8arr bsegs m DT jdt -> zlen jdt = FSE_DTABLE_SIZE tl ->
  u8arr bsegs m WK jw -> zlen jw = FSE_BUILD_DTABLE_WKSP_SIZE tl msv ->
  bytes_at bsegs m NC (u16s (map (Z_to_bv 64) nc)) -> Forall (fun c => - 32768 <= c < 32768) nc ->
  (* [comment removed for export] *)
  hblk8 LB DT (FSE_DTABLE_SIZE tl) -> hblk8 LB WK (FSE_BUILD_DTABLE_WKSP_SIZE tl msv) -> hblk8 LB NC (2 * zlen nc) ->
  DT mod 4 = 0 -> WK mod 2 = 0 -> NC mod 2 = 0 ->
  (DT + FSE_DTABLE_SIZE tl <= WK \/ WK + FSE_BUILD_DTABLE_WKSP_SIZE tl msv <= DT) ->
  (DT + FSE_DTABLE_SIZE tl <= NC \/ NC + 2 * zlen nc <= DT) ->
  (WK + FSE_BUILD_DTABLE_WKSP_SIZE tl msv <= NC \/ NC + 2 * zlen nc <= WK) ->
  (* [comment removed for export] *)
  stk bsegs m lo SPV -> ATOP + 4096 <= lo -> lo <= SPV - AFSE_BUILD_STACK -> SPV + 16 < al_top L -> SPV mod 16 = 0 ->
  mem_inv bsegs m ->
  rng RNG lo (al_top L - lo) -> rng_aimg RNG ->
  evtF bsegs RNG (fse_build_postA L RNG ra gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 FR fc st LB SPV DT WK msv tl d lo m)
       (MS (mkR ra (Z_to_bv 64 SPV) gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 DT) (Z_to_bv 64 NC) (Z_to_bv 64 msv) (Z_to_bv 64 tl)
                (Z_to_bv 64 WK) (Z_to_bv 64 wks) a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
           FR (Z_to_bv 64 AFSE_BUILD_DT) fc None m (seg_rom bsegs)).
End Stmts.
End CANSEC1.
